  1 │ /**
  2 │  * Real-kernel verification of the cgroup resource limits on evaluator commands (v1.1.4 WP-1105 / audit A9).
  3 │  *
  4 │  * Every check launches a command through the production evaluator-command runner (`createContainedRunner`, the code
  5 │  * behind `runArgv` that build and typecheck_clean use) with `resources` set small, and reads the kernel's own
  6 │  * counters. Nothing here is an injected runner: the only injected seam is a pass-through spy that keeps the
  7 │  * supervisor's report, which the runner otherwise reduces to status/signal/error.
  8 │  *
  9 │  * Skipped, with the reason printed, unless this host can run the contract for real: cgroup v2 with a systemd user
 10 │  * manager that delegates cpu+memory+pids, Bubblewrap, prlimit, and a dedicated tmpfs in
 11 │  * NEXUS_EVAL_TEST_WORKSPACE_ROOT (the same fixture `make test-ci` and CI provide). A skip is not verification.
 12 │  *
 13 │  * Safety: the supervisor applies and reads back memory.max, pids.max and cpu.max on the payload cgroup BEFORE the
 14 │  * command starts, and refuses (never runs the command) when it cannot. The hog, the fork bomb and the busy loops only
 15 │  * ever run inside that cgroup, with a wall-clock timeout.
 16 │  */
 17 │ import { test } from "node:test";
 18 │ import type { TestContext } from "node:test";
 19 │ import assert from "node:assert/strict";
 20 │ import fs from "node:fs";
 21 │ import os from "node:os";
 22 │ import path from "node:path";
 23 │ import { randomUUID } from "node:crypto";
 24 │ import { spawn, spawnSync } from "node:child_process";
 25 │ import { fileURLToPath } from "node:url";
 26 │ 
 27 │ const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
 28 │ const MIB = 1024 * 1024;
 29 │ const uid = process.getuid!();
 30 │ const USER_SERVICE = `/sys/fs/cgroup/user.slice/user-${uid}.slice/user@${uid}.service`;
 31 │ const SCOPE_GLOB_DIR = path.join(USER_SERVICE, "app.slice");
 32 │ 
 33 │ type Final = Record<string, any>;
 34 │ type Run = { result: any; final: Final | undefined; sampled: Sampled; marker: string; ms: number };
 35 │ type Sampled = { scopes: string[]; raw: Record<string, string> };
 36 │ 
 37 │ const read = (file: string) => { try { return fs.readFileSync(file, "utf8"); } catch { return null; } };
 38 │ const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
 39 │ 
 40 │ /** Why this host cannot verify the contract for real, or null. Computed once; the probe is a harmless `true` in a scope. */
 41 │ let gate: Promise<{ reason: string | null; resources?: any }> | undefined;
 42 │ function hostGate() {
 43 │   gate ??= (async () => {
 44 │     if (process.platform !== "linux") return { reason: "not Linux" };
 45 │     if (!fs.existsSync("/sys/fs/cgroup/cgroup.controllers")) return { reason: "no cgroup v2 unified hierarchy at /sys/fs/cgroup" };
 46 │     const delegated = read(path.join(USER_SERVICE, "cgroup.controllers"))?.trim().split(/\s+/) ?? [];
 47 │     for (const controller of ["cpu", "memory", "pids"]) {
 48 │       if (!delegated.includes(controller)) return { reason: `the systemd user manager does not delegate the ${controller} controller (${USER_SERVICE}/cgroup.controllers: "${delegated.join(" ")}")` };
 49 │     }
 50 │     if (!process.env.XDG_RUNTIME_DIR) return { reason: "XDG_RUNTIME_DIR is unset: no systemd user manager session" };
 51 │     const workspaceRoot = process.env.NEXUS_EVAL_TEST_WORKSPACE_ROOT;
 52 │     if (!workspaceRoot) return { reason: "NEXUS_EVAL_TEST_WORKSPACE_ROOT is unset: no dedicated capped tmpfs for the resource contract (run `make test-ci`)" };
 53 │     const { resourceProbeProblem } = await import(path.join(ROOT, "eval/resources.mjs"));
 54 │     const { sandboxAvailable } = await import(path.join(ROOT, "eval/isolate.mjs"));
 55 │     if (!sandboxAvailable()) return { reason: "Bubblewrap is unavailable or cannot start here" };
 56 │     if (!fs.existsSync("/usr/bin/prlimit")) return { reason: "prlimit is unavailable" };
 57 │     const tmpfs = fs.statfsSync(workspaceRoot);
 58 │     const resources = { cpuPercent: 50, memoryBytes: 64 * MIB, tasks: 16, storageBytes: tmpfs.blocks * tmpfs.bsize, workspaceRoot };
 59 │     const problem = resourceProbeProblem(resources);
 60 │     if (problem) return { reason: `the resource contract probe fails on this host: ${problem}` };
 61 │     return { reason: null, resources };
 62 │   })();
 63 │   return gate;
 64 │ }
 65 │ 
 66 │ /** Skip (with the reason) and return null, or the resources to use. */
 67 │ async function requireHost(t: TestContext) {
 68 │   const { reason, resources } = await hostGate();
 69 │   if (reason) { t.skip(`cannot verify cgroup limits on this host: ${reason}`); return null; }
 70 │   return resources;
 71 │ }
 72 │ 
 73 │ /** Scope cgroups (under the user manager) whose payload leaf holds a process whose command line contains `marker`. */
 74 │ function scopesHolding(marker: string) {
 75 │   const found: string[] = [];
 76 │   let entries: string[] = [];
 77 │   try { entries = fs.readdirSync(SCOPE_GLOB_DIR); } catch { return found; }
 78 │   for (const entry of entries) {
 79 │     if (!entry.startsWith("run-") || !entry.endsWith(".scope")) continue;
 80 │     const procs = read(path.join(SCOPE_GLOB_DIR, entry, "payload", "cgroup.procs"));
 81 │     if (!procs) continue;
 82 │     for (const pid of procs.split("\n").filter(Boolean)) {
 83 │       if ((read(`/proc/${pid}/cmdline`) ?? "").includes(marker)) { found.push(path.join(SCOPE_GLOB_DIR, entry)); break; }
 84 │     }
 85 │   }
 86 │   return found;
 87 │ }
 88 │ 
 89 │ /** Poll the cgroup files of this run's scope while it lives, as raw evidence next to the supervisor's report (informational: a short run can end between ticks). */
 90 │ function startSampler(marker: string): { stop: () => Sampled } {
 91 │   const scopes = new Set<string>();
 92 │   const raw: Record<string, string> = {};
 93 │   const timer = setInterval(() => {
 94 │     for (const scope of scopesHolding(marker)) {
 95 │       scopes.add(scope);
 96 │       for (const file of ["memory.events", "pids.events", "cpu.stat", "memory.max", "pids.max", "cpu.max", "memory.swap.max", "memory.oom.group"]) {
 97 │         const text = read(path.join(scope, "payload", file));
 98 │         if (text !== null) raw[file] = text.trim();
 99 │       }
100 │     }
101 │   }, 15);
102 │   return { stop: () => { clearInterval(timer); return { scopes: [...scopes], raw }; } };
103 │ }
104 │ 
105 │ async function launch(resources: any, command: string, args: string[], timeoutMs: number, opts: { env?: Record<string, string | undefined>; cwd?: string } = {}): Promise<Run> {
106 │   const { createContainedRunner } = await import(path.join(ROOT, "eval/evaluators/code/command.mjs"));
107 │   const { runIsolatedProcess } = await import(path.join(ROOT, "eval/isolate.mjs"));
108 │   let final: Final | undefined;
109 │   const runner = createContainedRunner({
110 │     runIsolatedProcess: async (spec: any, options: any) => { const outcome = await runIsolatedProcess(spec, options); final = outcome.resources; return outcome; },
111 │   });
112 │   const marker = `nexus-a9-${randomUUID()}`;
113 │   const cwd = opts.cwd ?? fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
114 │   const saved: Record<string, string | undefined> = {};
115 │   for (const [key, value] of Object.entries(opts.env ?? {})) { saved[key] = process.env[key]; if (value === undefined) delete process.env[key]; else process.env[key] = value; }
116 │   const sampler = startSampler(marker);
117 │   const started = Date.now();
118 │   try {
119 │     const result = await runner(command, [...args, marker], { cwd, timeoutMs, resources });
120 │     const ms = Date.now() - started;
121 │     return { result, final, sampled: sampler.stop(), marker, ms };
122 │   } finally {
123 │     sampler.stop();
124 │     for (const [key, value] of Object.entries(saved)) { if (value === undefined) delete process.env[key]; else process.env[key] = value; }
125 │     if (!opts.cwd) fs.rmSync(cwd, { recursive: true, force: true });
126 │   }
127 │ }
128 │ 
129 │ /** The shell script runs as `sh -c <script> <marker>`: `$0` carries the marker into every process's argv. */
130 │ const sh = (resources: any, script: string, timeoutMs: number, opts = {}) => launch(resources, "/bin/sh", ["-c", script], timeoutMs, opts);
131 │ 
132 │ /** The run's scope and everything in it is gone: no scope directory, no process carrying the marker. */
133 │ async function assertCleanedUp(run: Run, expectSeen = true) {
134 │   if (expectSeen) assert.ok(run.sampled.scopes.length >= 1, "the sampler never saw this run's scope, so cleanup would be vacuous");
135 │   const deadline = Date.now() + 8000;
136 │   let leftover: string[] = run.sampled.scopes.filter((scope) => fs.existsSync(scope));
137 │   while (leftover.length && Date.now() < deadline) { await sleep(100); leftover = run.sampled.scopes.filter((scope) => fs.existsSync(scope)); }
138 │   assert.deepEqual(leftover, [], "a transient scope cgroup outlived its command");
139 │   const pgrep = spawnSync("/usr/bin/pgrep", ["-f", run.marker], { encoding: "utf8" });
140 │   assert.equal(pgrep.status, 1, `a process carrying the run marker survived: ${pgrep.stdout}`);
141 │   assert.equal(run.final?.cleaned, true, JSON.stringify(run.final));
142 │ }
143 │ 
144 │ function note(t: TestContext, label: string, run: Run) {
145 │   t.diagnostic(`${label} ms=${run.ms} result=${JSON.stringify({ ...run.result, stdout: run.result.stdout.slice(0, 200), stderr: run.result.stderr.slice(0, 300) })}`);
146 │   t.diagnostic(`${label} supervisor-report=${JSON.stringify(run.final)}`);
147 │   for (const [file, text] of Object.entries(run.sampled.raw)) t.diagnostic(`${label} raw ${file}=${JSON.stringify(text)}`);
148 │ }
149 │ 
150 │ test("the host fixtures for the cgroup limit checks are reported (a skip below is not verification)", async (t) => {
151 │   const { reason } = await hostGate();
152 │   t.diagnostic(reason ? `SKIPPED: ${reason}` : `kernel ${os.release()} cgroup2 user delegation present; checks run for real`);
153 │ });
154 │ 
155 │ test("a memory hog is OOM-killed inside its cgroup, reported as a memory-limit kill, and the host is unaffected", { timeout: 60_000 }, async (t) => {
156 │   const resources = await requireHost(t);
157 │   if (!resources) return;
158 │   const hostAvailBefore = Number(/MemAvailable:\s+(\d+)/.exec(read("/proc/meminfo") ?? "")?.[1]);
159 │   // `tail` of an endless line without a newline buffers all of it: unbounded anonymous memory.
160 │   const run = await launch(resources, "/usr/bin/tail", ["/dev/zero"], 30_000);
161 │   note(t, "memory", run);
162 │   const final = run.final!;
163 │   assert.equal(final.limits["memory.max"], String(resources.memoryBytes), "the 64 MiB limit was read back from the kernel before the command ran");
164 │   assert.equal(final.limits["memory.swap.max"], "0");
165 │   assert.ok(final.oomKills >= 1, `memory.events oom_kill: ${JSON.stringify(final)}`);
166 │   assert.ok(final.memoryMaxEvents >= 1);
167 │   assert.ok(final.memoryPeakBytes <= resources.memoryBytes, `peak ${final.memoryPeakBytes} exceeded the limit`);
168 │   assert.notEqual(run.result.status, 0);
169 │   assert.equal(run.result.timedOut, false, "it died of the limit, not the wall clock");
170 │   assert.match(run.result.error ?? "", /memory limit/, "the operator is told a limit was hit");
171 │   await assertCleanedUp(run);
172 │   const hostAvailAfter = Number(/MemAvailable:\s+(\d+)/.exec(read("/proc/meminfo") ?? "")?.[1]);
173 │   // Coarse: other work shares this host. A hog that escaped its 64 MiB cgroup would eat memory until the host OOM killer ran.
174 │   assert.ok(hostAvailBefore - hostAvailAfter < 4 * 1024 * 1024 /* KiB */, `host MemAvailable dropped ${(hostAvailBefore - hostAvailAfter) / 1024} MiB`);
175 │ });
176 │ 
177 │ test("a shell that forks past pids.max gets EAGAIN and the contract reports it", { timeout: 60_000 }, async (t) => {
178 │   const resources = await requireHost(t);
179 │   if (!resources) return;
180 │   const run = await sh(resources, "for i in $(seq 40); do sleep 3 & done; wait", 20_000);
181 │   note(t, "pids-loop", run);
182 │   const final = run.final!;
183 │   assert.equal(final.limits["pids.max"], String(resources.tasks));
184 │   assert.ok(final.pidsMaxEvents >= 1, `pids.events max: ${JSON.stringify(final)}`);
185 │   assert.ok(final.pidsPeak <= resources.tasks, `pids.peak ${final.pidsPeak} > ${resources.tasks}`);
186 │   assert.match(run.result.stderr, /Cannot fork|Resource temporarily unavailable|EAGAIN/i, "the shell's own fork failed with EAGAIN");
187 │   await assertCleanedUp(run);
188 │ });
189 │ 
190 │ test("a real fork bomb is bounded by pids.max and killed with its cgroup; the host keeps forking", { timeout: 60_000 }, async (t) => {
191 │   const resources = await requireHost(t);
192 │   if (!resources) return;
193 │   // The classic bomb in a respawn loop, silenced (its error spam would hit the output cap), stopped by the wall clock, never outside the cgroup.
194 │   // bash survives a failed fork (dash exits on the first one), so the loop keeps bombing until the clock stops it.
195 │   const bomb = "b() { b | b & }; while :; do b 2>/dev/null; done";
196 │   const during: number[] = [];
197 │   const probe = setInterval(() => { during.push(spawnSync("/usr/bin/true").status ?? -1); }, 250);
198 │   let run: Run;
199 │   try { run = await launch(resources, "/usr/bin/bash", ["-c", bomb], 4000); } finally { clearInterval(probe); }
200 │   note(t, "fork-bomb", run);
201 │   const final = run.final!;
202 │   assert.equal(run.result.timedOut, true);
203 │   assert.ok(final.pidsMaxEvents >= 5, `pids.events max=${final.pidsMaxEvents}`);
204 │   assert.ok(final.pidsPeak <= resources.tasks, `pids.peak ${final.pidsPeak} > ${resources.tasks}`);
205 │   assert.ok(during.length >= 3 && during.every((status) => status === 0), `the host could not fork while the bomb ran: ${JSON.stringify(during)}`);
206 │   await assertCleanedUp(run);
207 │ });
208 │ 
209 │ for (const [cpuPercent, loops] of [[20, 2], [50, 3]] as const) {
210 │   test(`a CPU burner is throttled to cpu.max at ${cpuPercent}% (${loops} busy loops for 2 s)`, { timeout: 60_000 }, async (t) => {
211 │     const base = await requireHost(t);
212 │     if (!base) return;
213 │     const resources = { ...base, cpuPercent };
214 │     const busy = Array.from({ length: loops }, () => "timeout 2 sh -c 'while :; do :; done' &").join(" ");
215 │     const run = await sh(resources, `${busy} wait`, 20_000);
216 │     note(t, `cpu-${cpuPercent}`, run);
217 │     const final = run.final!;
218 │     const quotaUsec = (cpuPercent / 100) * 2_000_000;
219 │     t.diagnostic(`cpu-${cpuPercent} usage_usec=${final.cpuUsageUsec} throttled_usec=${final.cpuThrottledUsec} quota_over_2s_usec=${quotaUsec} unthrottled_demand_usec=${loops * 2_000_000}`);
220 │     assert.equal(final.limits["cpu.max"], `${cpuPercent * 1000} 100000`);
221 │     assert.ok(final.cpuThrottledUsec > 0, "cpu.stat throttled_usec must be > 0");
222 │     // Demand is `loops` full cores; the quota is a fraction of one. Allow a one-period burst and scheduler slack above,
223 │     // and require real progress below so the bound is the quota, not a stalled loop.
224 │     assert.ok(final.cpuUsageUsec <= quotaUsec * 1.5, `used ${final.cpuUsageUsec} us, quota allows ~${quotaUsec}`);
225 │     assert.ok(final.cpuUsageUsec >= quotaUsec * 0.25, `used only ${final.cpuUsageUsec} us, expected near ${quotaUsec}`);
226 │     assert.equal(run.result.error, null);
227 │     await assertCleanedUp(run);
228 │   });
229 │ }
