231 │ test("a clean command under the same limits succeeds untouched (the limits do not break ordinary work)", { timeout: 60_000 }, async (t) => {
232 │   const resources = await requireHost(t);
233 │   if (!resources) return;
234 │   const run = await sh(resources, "echo ok; sleep 0.3", 20_000);
235 │   note(t, "control", run);
236 │   assert.equal(run.result.status, 0);
237 │   assert.equal(run.result.error, null);
238 │   assert.equal(run.final?.oomKills, 0);
239 │   assert.equal(run.final?.pidsMaxEvents, 0);
240 │   await assertCleanedUp(run);
241 │ });
