243 │ test("without a usable systemd user manager a configured contract refuses to run the command (fails closed)", { timeout: 60_000 }, async (t) => {
244 │   const resources = await requireHost(t);
245 │   if (!resources) return;
246 │   for (const [label, env] of [
247 │     ["XDG_RUNTIME_DIR unset", { XDG_RUNTIME_DIR: undefined, DBUS_SESSION_BUS_ADDRESS: undefined }],
248 │     ["XDG_RUNTIME_DIR points at no user manager", { XDG_RUNTIME_DIR: path.join(os.tmpdir(), `no-user-manager-${randomUUID()}`), DBUS_SESSION_BUS_ADDRESS: undefined }],
249 │   ] as const) {
250 │     const cwd = fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
251 │     try {
252 │       const run = await sh(resources, "touch /workspace/ran; echo ran", 15_000, { env, cwd });
253 │       t.diagnostic(`fail-closed[${label}] result=${JSON.stringify(run.result)} report=${JSON.stringify(run.final)}`);
254 │       assert.notEqual(run.result.error, null, `${label}: the operator must get a diagnostic`);
255 │       assert.notEqual(run.result.status, 0, `${label}: must not look like a success`);
256 │       assert.doesNotMatch(run.result.stdout, /ran/, `${label}: the command ran without limits`);
257 │       assert.equal(fs.existsSync(path.join(cwd, "ran")), false, `${label}: the command ran without limits`);
258 │     } finally { fs.rmSync(cwd, { recursive: true, force: true }); }
259 │   }
260 │ });
261 │ 
262 │ test("when the cgroup parent is not writable the supervisor refuses before the command starts (fails closed)", { timeout: 60_000 }, async (t) => {
263 │   const resources = await requireHost(t);
264 │   if (!resources) return;
265 │   // Run the same production runner in a child whose /sys/fs/cgroup is a read-only bind: the supervisor, started in
266 │   // this mount namespace by systemd-run, cannot create its leaves, which is what a host without delegation looks like.
267 │   const cwd = fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
268 │   const script = `
269 │     import { createContainedRunner } from ${JSON.stringify(path.join(ROOT, "eval/evaluators/code/command.mjs"))};
270 │     const run = createContainedRunner();
271 │     const cwd = ${JSON.stringify(cwd)};
272 │     const result = await run("/bin/sh", ["-c", "touch /workspace/ran; echo ran"], { cwd, timeoutMs: 15000, resources: ${JSON.stringify(resources)} });
273 │     console.log(JSON.stringify(result));`;
274 │   const child = spawnSync("/usr/bin/bwrap", [
275 │     "--bind", "/", "/", "--dev-bind", "/dev", "/dev", "--ro-bind", "/sys/fs/cgroup", "/sys/fs/cgroup",
276 │     "--die-with-parent", "--", process.execPath, "--input-type=module", "-e", script,
277 │   ], { encoding: "utf8", timeout: 40_000, env: { PATH: "/usr/bin:/bin", XDG_RUNTIME_DIR: process.env.XDG_RUNTIME_DIR, DBUS_SESSION_BUS_ADDRESS: process.env.DBUS_SESSION_BUS_ADDRESS ?? "" } });
278 │   t.diagnostic(`readonly-cgroup bwrap status=${child.status} stdout=${child.stdout.trim().slice(-600)} stderr=${child.stderr.trim().slice(-300)}`);
279 │   if (child.status !== 0) { t.skip(`cannot simulate an unwritable cgroup parent here (outer bwrap failed: ${child.stderr.trim().slice(-200)})`); return; }
280 │   const result = JSON.parse(child.stdout.trim().split("\n").pop()!);
281 │   assert.match(result.error ?? "", /could not apply resource limits|resource supervisor/, JSON.stringify(result));
282 │   assert.notEqual(result.status, 0);
283 │   assert.equal(fs.existsSync(path.join(cwd, "ran")), false, "the command ran without its limits");
284 │   fs.rmSync(cwd, { recursive: true, force: true });
285 │ });

