  1 │ // Kernel-enforced resource contract for task-controlled executions (eval/README.md, "Resource contract").
  2 │ // Each execution runs in its own delegated transient systemd --user scope under eval/cgroup_supervisor.mjs, which
  3 │ // applies cgroup v2 cpu.max, memory.max (swap 0) and pids.max to a payload leaf, verifies them, and kills the whole
  4 │ // cgroup afterwards. Workspaces and homes live on a dedicated size-capped tmpfs (storageBytes): that cap bounds
  5 │ // everything a run keeps on disk across phases, and each phase's writes are additionally charged to its memory.max.
  6 │ import { spawn, spawnSync } from "node:child_process";
  7 │ import fs from "node:fs";
  8 │ import path from "node:path";
  9 │ import { fileURLToPath } from "node:url";
 10 │ 
 11 │ const SYSTEMD_RUN = "/usr/bin/systemd-run";
 12 │ const SUPERVISOR = fileURLToPath(new URL("./cgroup_supervisor.mjs", import.meta.url));
 13 │ const TMPFS_MAGIC = 0x01021994;
 14 │ 
 15 │ /** Null when `resources` is a complete, sane contract; otherwise why it is not. */
 16 │ export function resourceConfigProblem(resources) {
 17 │   if (!resources || typeof resources !== "object") return "resources must set cpuPercent, memoryBytes, tasks, storageBytes and workspaceRoot";
 18 │   const { cpuPercent, memoryBytes, tasks, storageBytes, workspaceRoot } = resources;
 19 │   if (!Number.isInteger(cpuPercent) || cpuPercent < 10 || cpuPercent > 100 * 1024) return "resources.cpuPercent must be an integer from 10 to 102400";
 20 │   if (!Number.isInteger(memoryBytes) || memoryBytes < 64 * 1024 * 1024 || memoryBytes % 4096 !== 0) return "resources.memoryBytes must be a multiple of 4096 of at least 64 MiB";
 21 │   if (!Number.isInteger(tasks) || tasks < 8 || tasks > 1 << 20) return "resources.tasks must be an integer from 8 to 1048576";
 22 │   if (!Number.isInteger(storageBytes) || storageBytes < 64 * 1024 * 1024) return "resources.storageBytes must be an integer of at least 64 MiB";
 23 │   if (typeof workspaceRoot !== "string" || !path.isAbsolute(workspaceRoot)) return "resources.workspaceRoot must be an absolute path";
 24 │   let stat;
 25 │   try { stat = fs.statfsSync(workspaceRoot); }
 26 │   catch { return "resources.workspaceRoot is unavailable"; }
 27 │   if (stat.type !== TMPFS_MAGIC) return "resources.workspaceRoot must be on a tmpfs so candidate writes are charged to the run's memory limit";
 28 │   const mountProblem = dedicatedTmpfsMountProblem(workspaceRoot);
 29 │   if (mountProblem) return mountProblem;
 30 │   if (stat.blocks * stat.bsize > storageBytes) return `resources.workspaceRoot tmpfs is ${stat.blocks * stat.bsize} bytes; mount a dedicated tmpfs with size<=storageBytes (${storageBytes})`;
 31 │   return null;
 32 │ }
