 34 │ /** A subdirectory of a shared tmpfs (including /dev/shm) does not enforce a per-run storage cap. */
 35 │ export function dedicatedTmpfsMountProblem(workspaceRoot, mountInfoText = null) {
 36 │   let lines;
 37 │   try { lines = (mountInfoText ?? fs.readFileSync("/proc/self/mountinfo", "utf8")).split("\n"); }
 38 │   catch { return "resources.workspaceRoot mount table is unavailable; refusing unverified workspace storage limits"; }
 39 │   const decode = (value) => value.replace(/\\([0-7]{3})/g, (_match, octal) => String.fromCharCode(Number.parseInt(octal, 8)));
 40 │   const expected = path.resolve(workspaceRoot);
 41 │   const matching = lines.filter((entry) => {
 42 │     const fields = entry.split(" ");
 43 │     return fields.length > 6 && decode(fields[4]) === expected;
 44 │   });
 45 │   if (matching.length > 1) return "resources.workspaceRoot has stacked or duplicate mount records; refusing ambiguous workspace storage boundary";
 46 │   const line = matching[0];
 47 │   if (!line) return "resources.workspaceRoot must be the exact mount point of a dedicated tmpfs, not a subdirectory";
 48 │   const fields = line.split(" ");
 49 │   const separator = fields.indexOf("-");
 50 │   if (separator < 0 || fields[separator + 1] !== "tmpfs" || decode(fields[3]) !== "/") {
 51 │     return "resources.workspaceRoot must be its own tmpfs mount, not a shared or bind-mounted filesystem";
 52 │   }
 53 │   // A bind mount of a tmpfs root retains the same major:minor and root fields. Reject aliases of
 54 │   // this mount so an apparently dedicated path cannot expose a tmpfs shared at another path.
 55 │   const device = fields[2];
 56 │   const aliases = lines.filter((entry) => {
 57 │     const other = entry.split(" ");
 58 │     return other.length > 6 && other[2] === device && decode(other[4]) !== expected;
 59 │   });
 60 │   if (aliases.length > 0) return "resources.workspaceRoot tmpfs is also mounted elsewhere; bind/shared mounts are not allowed";
 61 │   const options = `${fields[5]},${fields[separator + 3] ?? ""}`.split(",");
 62 │   const mode = options.find((option) => option.startsWith("mode="))?.slice(5);
 63 │   const uid = options.find((option) => option.startsWith("uid="))?.slice(4);
 64 │   const mountMode = mode ? Number.parseInt(mode, 8) : null;
 65 │   if (mountMode === null || (mountMode & 0o700) !== 0o700 || (mountMode & 0o066) !== 0 || uid !== String(process.getuid())) {
 66 │     return "dedicated tmpfs must be owner-accessible, non-readable/non-writable by group or other, and owned by the evaluator harness uid";
 67 │   }
 68 │   let rootStat;
 69 │   try { rootStat = fs.statSync(expected); }
 70 │   catch { return "resources.workspaceRoot mount root cannot be inspected; refusing unverified workspace permissions"; }
 71 │   const rootMode = rootStat.mode & 0o777;
 72 │   if (rootStat.uid !== process.getuid() || (rootMode & 0o700) !== 0o700 || (rootMode & 0o066) !== 0) {
 73 │     return "dedicated tmpfs effective mount root must be owner-accessible, non-readable/non-writable by group or other, and owned by the evaluator harness uid";
 74 │   }
 75 │   return null;
 76 │ }
