 96 │ /** The command line that runs `spec` under the supervisor in a fresh scope with `resources` applied. */
 97 │ export function containedSpec(spec, resources) {
 98 │   const { XDG_RUNTIME_DIR, DBUS_SESSION_BUS_ADDRESS } = process.env;
 99 │   if (!XDG_RUNTIME_DIR) throw new Error("resource containment needs the systemd user manager (XDG_RUNTIME_DIR is unset)");
100 │   if (!fs.existsSync(SYSTEMD_RUN)) throw new Error("resource containment needs systemd-run");
101 │   const limits = { cpuPercent: resources.cpuPercent, memoryBytes: resources.memoryBytes, tasks: resources.tasks };
102 │   return {
103 │     cmd: SYSTEMD_RUN,
104 │     argv: ["--user", "--scope", "--quiet", "--collect", "-p", "Delegate=yes", "--", process.execPath, SUPERVISOR, JSON.stringify({ limits, cmd: spec.cmd, argv: spec.argv })],
105 │     env: { XDG_RUNTIME_DIR, ...(DBUS_SESSION_BUS_ADDRESS ? { DBUS_SESSION_BUS_ADDRESS } : {}) },
106 │     timeoutMs: spec.timeoutMs,
107 │   };
108 │ }
