110 │ /**
111 │  * Spawn `spec` (contained when `resources` is set). `containment.kill()` empties the payload cgroup;
112 │  * `containment.final` resolves to the supervisor's last report, or null when it never reported.
113 │  */
114 │ export function spawnContained(spec, resources, { stdio, ...options }) {
115 │   if (!resources) return { child: spawn(spec.cmd, spec.argv, { ...options, stdio, env: options.env ?? {} }), containment: null };
116 │   const wrapped = containedSpec(spec, resources);
117 │   const child = spawn(wrapped.cmd, wrapped.argv, { ...options, env: wrapped.env, stdio: [...stdio, "pipe", "pipe"] });
118 │   const control = child.stdio[4];
119 │   let text = "";
120 │   let cgroup = null;
121 │   const final = new Promise((resolve) => {
122 │     child.stdio[3].on("data", (chunk) => {
123 │       text += chunk.toString("utf8");
124 │       const reports = parseReports(text);
125 │       cgroup ??= reports.cgroup;
126 │       // Close the supervisor's control pipe after its final report. Otherwise the parent write end can
127 │       // keep ChildProcess's `close` event pending even though the supervised command and scope have exited.
128 │       if (reports.final && control && !control.destroyed) control.end();
129 │     });
130 │     child.stdio[3].on("close", () => resolve(parseReports(text).final));
131 │     child.on("error", () => resolve(null));
132 │   });
133 │   const signal = (name, graceMs = 5000) => {
134 │     if (name !== "SIGTERM" || !Number.isSafeInteger(graceMs) || graceMs < 0 || graceMs > 30_000) {
135 │       throw new Error("contained payload supports SIGTERM with a grace period from 0 to 30000 ms");
136 │     }
137 │     if (!control || control.destroyed || !control.writable) return false;
138 │     return control.write(`${JSON.stringify({ type: "signal", name, graceMs })}\n`);
139 │   };
140 │   let repeat = null;
